(async () => {
  const sessionId = new URL(location.href).searchParams.get("session") ?? "11111111-2222-4333-8444-555555555555";
  const rows = [...document.querySelectorAll("[data-material-key]")].filter(row => row.getClientRects().length && row.querySelector(".h1-material-name")?.textContent.trim() === "Recursion cards" && /\b1 card\b/.test(row.innerText)).map(row => ({ key: row.dataset.materialKey, label: row.innerText }));
  if (!rows.length) return false;
  console.log("[keating:materials] " + JSON.stringify({ action: "Inspect Materials", count: rows.length }));
  if (rows.length > 1) {
    const { sessions, keatingStorage } = await import("/src/hooks/keating-storage.ts");
    const presentations = (await keatingStorage.getOpenUiPresentations(sessionId)).map(({ id, documentId, nodeId, createdAt }) => ({ id, documentId, nodeId, createdAt }));
    const stored = await sessions.loadSession(sessionId);
    const messages = (stored?.messages ?? []).map(({ id, timestamp, role }) => ({ id: id ?? null, timestamp, role }));
    const transcriptIds = [...document.querySelectorAll("[data-learning-message-ids], [data-message-id]")].map(row => row.dataset.learningMessageIds ?? row.dataset.messageId);
    const data = JSON.stringify({ sessionId, at: Date.now(), rows, presentations, messages, transcriptIds });
    const chunks = data.match(/.{1,225}/gs);
    chunks.forEach((part, index) => console.log("[keating:w3-duplicate] " + JSON.stringify({ index, count: chunks.length, part })));
    throw new Error("Expected one new deck in Materials, saw " + rows.length);
  }
  return true;
})()
